        const ty = api.rnd(30, api.h - 70)
        const dx = tx - ship.x
        const dy = ty - ship.y
        const d = dx * dx + dy * dy
        if (d > best) { best = d; x = tx; y = ty }
        if (d > 120 * 120) { x = tx; y = ty; break }
