        api.circle(bikeX + 12 + sx, BIKE_Y + 14, 9, '#39424a')
        api.rect(bikeX - 14 + sx, BIKE_Y, 28, 4, C.accent)
        api.rect(bikeX + sx, BIKE_Y - 18, 4, 18, C.accent)
        api.circle(bikeX + 2 + sx, BIKE_Y - 22, 7, C.accent2)
