      api.text('CLEAR ' + cleared + '/2', W / 2, 20, { size: 13, color: C.dim, align: 'center' })
      api.text('LIVES ' + lives, W - 12, 20, { size: 13, color: lives > 1 ? C.dim : C.warn, align: 'right' })
