    let piece = null
    let nextKind = api.irnd(0, SHAPES.length - 1)
    let drop = 0
    let interval = 0.62
    let cleared = 0
    let dead = false
    let combo = 0
    let comboTimer = 0
    let shake = 0
    let shx = 0
    let shy = 0
