      if (!s) {
        shot[i] = 1
        combo = 0
        comboT = 0
        burst(i, 5, C.accent)
        msg = 'MISS - KEEP FIRING'
        msgColor = C.dim
        pop = { text: 'MISS', color: C.dim, t: 0 }
        return
      }
      shot[i] = 2
      s.hits += 1
      combo += 1
      comboT = 3.5
