        api.text('2048 3x3 - MAKE A 32', 16, 22, { size: 14, color: C.dim, weight: 'bold' })
        api.text('SCORE ' + score, 400, 22, { size: 14, color: scoreT > 0 ? C.good : C.fg, align: 'center', weight: 'bold' })
