      api.text('candy ' + fed, W - 14, 18, { size: 12, color: C.dim, align: 'right' })
      for (let i = 0; i < 3; i += 1) api.rect(12 + i * 14, 30, 9, 9, i < misses ? C.warn : C.panel)
