          let pvy = v.vy;
          for (let k = 0; k < 26; k += 1) {
            pvy += 380 * 0.045;
            pvx += wind * 0.045;
            px += pvx * 0.045;
            py += pvy * 0.045;
            if (py > 344) break;
            api.circle(px, py, 2.2, 'rgba(232,238,246,' + (0.5 - k * 0.015).toFixed(2) + ')');
          }
