    for (let y = 3; y <= 6; y += 1) wall(5, y)
    for (let y = 8; y <= 12; y += 1) wall(14, y)
    for (let x = 8; x <= 12; x += 1) wall(x, 4)
    for (let x = 2; x <= 6; x += 1) wall(x, 11)
    for (let x = 16; x <= 18; x += 1) wall(x, 9)

