          const s = snake[i]
          const head = i === 0
          const pad = head ? 1 : 3
          const col = dead ? api.colors.dim : head ? api.colors.good : api.colors.accent
          api.rect(s.x * C + pad + shx, s.y * C + pad + shy, C - pad * 2, C - pad * 2, col)
