        Rr(l.x, y, l.w, 2, 'rgba(232,238,246,0.22)')
        Rr(l.x, y + LH - 2, l.w, 2, 'rgba(16,20,24,0.25)')
        if (l.w > 60) Rr(l.x + l.w / 2 - 1, y + 6, 2, LH - 12, 'rgba(16,20,24,0.12)')
