      const oy = shake > 0 ? Math.cos(api.now() * 0.1) * 3.4 * shake : 0
      const Rr = (x, y, w, h, c) => api.rect(x + ox, y + oy, w, h, c)
      for (let i = 0; i < 9; i += 1) {
        const y = 30 + ((i * 38 + t * 7) % (H - 30))
        Rr(0, y, W, 1, 'rgba(143,160,180,0.05)')
      }
