        if (api.down('up')) vy -= 1
        if (api.down('down')) vy += 1
        if (vx !== 0 || vy !== 0) {
          const n = Math.hypot(vx, vy)
          P.x += (vx / n) * SPEED * dt
          P.y += (vy / n) * SPEED * dt
        }
        P.x = Math.max(10, Math.min(W - 10, P.x))
        P.y = Math.max(28, Math.min(H - 12, P.y))
