        litT = Math.max(0, litT - dt * 2.2)
        warn = Math.max(0, warn - dt * 2.5)
        shake = Math.max(0, shake - dt * 5)
        banner = Math.max(0, banner - dt * 1.4)
        msgT = Math.max(0, msgT - dt * 1.4)
