      if (combo > 1) api.text('COMBO x' + combo, 12, 36, { size: 13, color: C.accent2 })
      if (msgT > 0) api.text(msg, W / 2, 60, { size: 20, color: C.accent2, align: 'center', weight: 'bold' })
