      p.y += p.vy * sdt
      if (p.y >= GROUND - PH) {
        if (!p.ground) spark(p.x + PW / 2, GROUND - 2, 4, C.dim, 88)
        p.y = GROUND - PH
        p.vy = 0
        p.ground = true
        p.air = 1
      }

