          if (done) fill = C.good
          else if (cur) fill = flashT > 0 && !okFlash ? C.warn : C.accent
          api.rect(x, y, bw, bw, fill)
          api.text(word[i].toUpperCase(), x + bw / 2, y + bw / 2 + 1, {
            size: 28, color: done || cur ? '#0d1218' : C.dim, align: 'center', weight: 'bold',
          })
