        if (combo > 1) api.text('x' + combo, api.w - 106, 27, { size: 15, color: C.good, align: 'right', weight: 'bold' })
        const sx = shakeT > 0 ? Math.sin(shakeT * 78) * 8 * (shakeT / 0.3) : 0
